<script setup lang="ts">
import { computed, inject, onBeforeUnmount, ref, watch, type Ref } from 'vue'
import { useQuery, useQueryClient } from '@tanstack/vue-query'
import { useRoute, useRouter, onBeforeRouteLeave, onBeforeRouteUpdate } from 'vue-router'
import { ArrowRight, Plus, Play, FlaskConical, Download, RotateCcw, X, Check, ShieldCheck, Pin } from '@lucide/vue'
import { api, post, percent, ms, pretty, human, type Project, type Report, type Execution, type Resource, type Version, type Obj, type User } from '@/api/client'
import { Button } from '@/components/ui/button'
import JsonView from '@/components/JsonView.vue'
import Status from '@/components/Status.vue'
import ResourceEditor from '@/components/ResourceEditor.vue'
import ModalFrame from '@/components/ModalFrame.vue'
import GateEditor from '@/components/GateEditor.vue'
import JsonField from '@/components/JsonField.vue'
import ImportedOutputEditor from '@/components/ImportedOutputEditor.vue'
const route = useRoute(), router = useRouter(), cache = useQueryClient()
const currentProject = inject<Ref<string>>('projectId')!
const currentUser = inject<Ref<User>>('user')!
const role = computed(() => currentUser.value?.workspaces.find(w => w.id === project.data.value?.workspace_id)?.role || 'viewer')
const canEdit = computed(() => role.value !== 'viewer')
const canAdmin = computed(() => role.value === 'owner')
const page = computed(() => route.params.executionId ? 'case' : route.params.experimentId ? 'results' : String(route.params.page || 'overview'))
const experimentId = computed(() => String(route.params.experimentId || ''))
const experiment = useQuery({ queryKey: computed(() => ['experiment', experimentId.value]), queryFn: () => api<Report>(`/experiments/${experimentId.value}`), enabled: computed(() => !!experimentId.value), refetchInterval: query => ['queued','running'].includes(query.state.data?.status || '') ? 2500 : false })
const projectId = computed(() => experimentId.value ? experiment.data.value?.project_id || '' : currentProject.value)
const project = useQuery({ queryKey: computed(() => ['project', projectId.value]), queryFn: () => api<Project>(`/projects/${projectId.value}`), enabled: computed(() => !!projectId.value), refetchInterval: 4000 })
const selectedVersion = ref(''), selectedResource = ref<Resource | null>(null)
const execution = useQuery({ queryKey: computed(() => ['execution', route.params.executionId]), queryFn: () => api<Execution>(`/executions/${route.params.executionId}`), enabled: computed(() => !!route.params.executionId) })
const reviewQueue = useQuery({ queryKey: computed(() => ['reviews', projectId.value]), queryFn: () => api<Execution[]>(`/projects/${projectId.value}/reviews`), enabled: computed(() => page.value === 'reviews' && !!projectId.value) })
const gateConfig = useQuery({ queryKey: computed(() => ['gate-config', projectId.value]), queryFn: () => api<Obj>(`/projects/${projectId.value}/gate`), enabled: computed(() => page.value === 'gates' && !!projectId.value) })
const settingsData = useQuery({ queryKey: computed(() => ['settings', projectId.value]), queryFn: async () => ({ credentials: await api<Obj[]>(`/projects/${projectId.value}/credentials`), tokens: await api<Obj[]>('/tokens'), audit: await api<Obj[]>(`/projects/${projectId.value}/audit`), members: await api<Obj[]>(`/workspaces/${project.data.value?.workspace_id}/members`) }), enabled: computed(() => page.value === 'settings' && !!project.data.value) })
const resources = (kind: string) => project.data.value?.resources.filter(r => r.kind === kind) || []
const versions = (kind: string) => resources(kind).flatMap(r => r.versions.map(v => ({ ...v, label: `${r.name} · v${v.number}` })))
const titles: Record<string,string> = { overview: 'Project overview', datasets: 'Datasets', targets: 'Targets', evaluators: 'Evaluators & suites', experiments: 'Experiments', reviews: 'Human review', gates: 'CI gates & reports', settings: 'Project settings' }
const title = computed(() => page.value === 'results' ? experiment.data.value?.name || 'Experiment results' : page.value === 'case' ? execution.data.value?.case_id || 'Case detail' : titles[page.value] || 'Page not found')
const notice = ref(''), error = ref(''), busy = ref(false), modal = ref(''), formName = ref(''), editorKind = ref('dataset')
const datasetId = ref(''), targetId = ref(''), suiteId = ref(''), launchMode = ref('http'), repetitions = ref(1), concurrency = ref(2), budget = ref<number>(), launchName = ref(''), imported = ref('[]')
const gateExperiment = ref(''), metric = ref('field_accuracy'), gateResult = ref<Obj | null>(null)
const reviewMetric = ref(''), reviewNote = ref(''), reviewPassed = ref(false), onlyUnreviewed = ref(true)
const secretName = ref(''), secretValue = ref(''), tokenName = ref('CI pipeline'), newToken = ref(''), member = ref({ email: '', name: '', password: '', role: 'viewer' })
const testResult = ref<Obj | null>(null), filter = ref('all')
const latestId = computed(() => project.data.value?.experiments.find(e => e.status === 'completed')?.id || '')
const latest = useQuery({ queryKey: computed(() => ['latest', latestId.value]), queryFn: () => api<Report>(`/experiments/${latestId.value}`), enabled: computed(() => page.value === 'overview' && !!latestId.value) })
const queryError = computed(() => [project.error.value, experiment.error.value, execution.error.value, reviewQueue.error.value, gateConfig.error.value, settingsData.error.value].find(Boolean))
const displayReviews = computed(() => reviewQueue.data.value?.filter(r => (!onlyUnreviewed.value || !r.reviews.length) && (!reviewSearch.value || `${r.case_id} ${r.experiment_name}`.toLowerCase().includes(reviewSearch.value.toLowerCase()))) || [])
const filteredRows = computed(() => experiment.data.value?.executions.filter(r => filter.value === 'all' || (filter.value === 'failing' ? r.results.some(e => e.passed === false) : r.status !== 'completed')) || [])
const resourceSearch = ref(''), experimentSearch = ref(''), experimentStatus = ref(''), reviewSearch = ref('')
const workspaceTokens = computed(() => settingsData.data.value?.tokens.filter(t => t.workspace_id === project.data.value?.workspace_id) || [])
const tokenScope = ref('read'), tokenDays = ref(30), copied = ref(false)
const metricKeys = computed(() => [...new Set(versions('evaluator').map(v => String(v.config.metric_key)))])
const overviewMetric = computed(() => Object.keys(latest.data.value?.summary.metrics || {}).find(k => k === 'field_accuracy') || Object.keys(latest.data.value?.summary.metrics || {})[0] || '')
const visibleExperiments = computed(() => (project.data.value?.experiments || []).filter(e => (!experimentStatus.value || e.status === experimentStatus.value) && e.name.toLowerCase().includes(experimentSearch.value.toLowerCase())))
const visibleResources = (kind: string) => resources(kind).filter(r => r.name.toLowerCase().includes(resourceSearch.value.toLowerCase()))
const baselineLabel = computed(() => { const b = project.data.value?.baselines.find(b => b.name === 'main'); return project.data.value?.experiments.find(e => e.id === b?.experiment_id)?.name || (b ? b.experiment_id.slice(0,8) : 'No baseline pinned yet') })
const hasImportedOutputs = computed(() => !!project.data.value?.experiments.some(e => e.mode === 'imported' && ['completed', 'partially_failed'].includes(e.status)))
const readiness = computed(() => [
 { label: 'Create a dataset', hint: 'Define inputs and expected behavior.', key: 'datasets', done: !!versions('dataset').length },
 { label: 'Provide outputs', hint: hasImportedOutputs.value ? 'Saved outputs are ready to evaluate.' : 'Connect an HTTP target or import saved outputs.', key: hasImportedOutputs.value ? 'experiments' : 'targets', done: hasImportedOutputs.value || !!versions('target').length },
 { label: 'Build an evaluation suite', hint: 'Select and pin the criteria for a run.', key: 'evaluators', done: !!versions('suite').length },
 { label: 'Run and pin a baseline', hint: 'Capture the reference for future comparisons.', key: 'experiments', done: !!project.data.value?.baselines.length },
])
const progress = computed(() => { const all = experiment.data.value?.executions || []; const done = all.filter(e => !['queued', 'running'].includes(e.status)).length; return { done, total: all.length, percent: all.length ? done / all.length * 100 : 0 } })
const launchDataset = useQuery({ queryKey: computed(() => ['launch-dataset', datasetId.value]), queryFn: () => api<Version & { cases: Obj[] }>(`/versions/${datasetId.value}`), enabled: computed(() => modal.value === 'launch' && !!datasetId.value) })
const plannedCalls = computed(() => (launchDataset.data.value?.cases.length || 0) * Number(repetitions.value))
const launchMissing = computed(() => !datasetId.value ? 'Create a dataset before starting a run.' : !suiteId.value ? 'Create an evaluation suite before starting a run.' : launchMode.value === 'http' && !targetId.value ? 'Configure a target, or choose imported outputs.' : '')
watch(launchMode, () => { launchValid.value = true })
const launchValid = ref(true), testValid = ref(true), testJson = ref<unknown>({})
const launchSnapshot = () => JSON.stringify([launchName.value,datasetId.value,targetId.value,suiteId.value,launchMode.value,repetitions.value,concurrency.value,budget.value,imported.value])
let originalLaunch = ''
function closeModal() { if (busy.value) return; if (modal.value === 'launch' && originalLaunch !== launchSnapshot() && !window.confirm('Discard this experiment draft?')) return; modal.value = ''; error.value = '' }
const guardLaunch = () => modal.value !== 'launch' || originalLaunch === launchSnapshot() || window.confirm('Leave without launching this experiment?')
onBeforeRouteLeave(guardLaunch)
onBeforeRouteUpdate(guardLaunch)
function unloadDraft(event: BeforeUnloadEvent) { if (modal.value === 'launch' && originalLaunch !== launchSnapshot()) { event.preventDefault(); event.returnValue = '' } }
window.addEventListener('beforeunload', unloadDraft)
onBeforeUnmount(() => window.removeEventListener('beforeunload', unloadDraft))
async function resourceSaved() { modal.value = ''; notice.value = 'Immutable version saved'; await cache.invalidateQueries() }
async function copyToken() { try { await navigator.clipboard.writeText(newToken.value); copied.value = true } catch { error.value = 'Clipboard is unavailable. Select and copy the token manually.' } }
let formProject = ''
watch(() => project.data.value, p => { if (p) { if (!metricKeys.value.includes(metric.value)) metric.value = metricKeys.value[0] || '';  if (formProject !== p.id) { datasetId.value = ''; targetId.value = ''; suiteId.value = ''; gateExperiment.value = ''; launchMode.value = versions('target').length ? 'http' : 'imported'; imported.value = '[]'; formProject = p.id }; datasetId.value ||= versions('dataset')[0]?.id || ''; targetId.value ||= versions('target')[0]?.id || ''; suiteId.value ||= versions('suite').find(v => v.label.includes('Release'))?.id || versions('suite')[0]?.id || ''; gateExperiment.value ||= p.experiments[0]?.id || '' } }, { immediate: true })
watch(modal, value => { if (value === 'launch') originalLaunch = launchSnapshot(); if (value) error.value = '' })
watch(() => execution.data.value, v => { if (v) reviewMetric.value = v.results[0]?.metric_key || '' })
async function action(fn: () => Promise<unknown>, message = 'Saved') { busy.value = true; error.value = ''; try { await fn(); notice.value = message; await cache.invalidateQueries() } catch (e) { error.value = (e as Error).message } finally { busy.value = false } }
function openCreate(kind: string) { selectedResource.value = null; editorKind.value = kind; modal.value = 'resource'; error.value = '' }
function openEdit(r: Resource) { selectedResource.value = r; editorKind.value = r.kind; modal.value = 'resource'; error.value = '' }
async function launchExperiment() { await action(async () => { const result = await post<Report>(`/projects/${projectId.value}/experiments`, { name: launchName.value || `Experiment ${new Date().toLocaleString()}`, dataset_version_id: datasetId.value, target_version_id: launchMode.value === 'http' ? targetId.value : null, suite_version_id: suiteId.value, repetitions: Number(repetitions.value), concurrency: Number(concurrency.value), mode: launchMode.value, imports: launchMode.value === 'imported' ? JSON.parse(imported.value) : [], import_dataset_version_id: launchMode.value === 'imported' ? datasetId.value : null, max_target_calls: budget.value || null }); modal.value = ''; router.push(`/experiments/${result.id}`) }, 'Experiment queued') }
async function rescore() { await action(async () => { const e = experiment.data.value!; const r = await post<Report>(`/experiments/${e.id}/rescore`, { suite_version_id: suiteId.value || e.suite_version_id, name: `${e.name} · rescore` }); router.push(`/experiments/${r.id}`) }, 'Saved outputs queued for rescoring') }
async function saveReview() { await action(async () => { await post(`/executions/${route.params.executionId}/reviews`, { metric_key: reviewMetric.value, passed: reviewPassed.value, note: reviewNote.value }); reviewNote.value = '' }, 'Human assessment saved; automated result preserved') }
async function createSecret() { await action(async () => { await post(`/projects/${projectId.value}/credentials`, { name: secretName.value, value: secretValue.value }); secretValue.value = '' }, 'Encrypted credential saved') }
async function createToken() { await action(async () => { const r = await post<Obj>('/tokens', { workspace_id: project.data.value?.workspace_id, name: tokenName.value, scopes: tokenScope.value === 'write' ? ['read','write'] : ['read'], days: Number(tokenDays.value) }); newToken.value = r.token; copied.value = false }, 'Token created; copy it now') }
</script>
<template>
<main id="main-content" class="content" tabindex="-1">
  <RouterLink v-if="page === 'case' || page === 'results'" :to="page === 'case' && execution.data.value?.experiment_id ? `/experiments/${execution.data.value.experiment_id}` : `/projects/${projectId}/experiments`" class="back-link">← {{ page === 'case' ? 'Back to experiment' : 'All experiments' }}</RouterLink><div class="page-heading"><div><h1>{{ title }}</h1></div><div class="heading-actions"><span v-if="project.data.value?.fixture" class="fixture-chip">Deterministic fixtures</span><Button v-if="canEdit && ['overview','experiments'].includes(page)" @click="modal = 'launch'"><Plus :size="16"/>New experiment</Button><Button v-if="canEdit && ['datasets','targets','evaluators'].includes(page)" @click="openCreate(page === 'datasets' ? 'dataset' : page === 'targets' ? 'target' : 'evaluator')"><Plus :size="16"/>Create new</Button></div></div>
  <div v-if="!canEdit && project.data.value" class="info-strip">Viewer access. You can inspect and export results; editing requires an editor or owner.</div><div v-if="error || queryError" class="error" role="alert">{{ error || (queryError as Error)?.message }}</div><div v-if="notice" class="notice" role="status"><Check :size="15"/>{{ notice }}<button aria-label="Dismiss notification" @click="notice = ''"><X :size="14"/></button></div>
  <div v-if="!titles[page] && !['results','case'].includes(page)" class="empty-state panel"><h3>This page does not exist</h3><RouterLink :to="`/projects/${projectId}/overview`" class="text-link">Back to overview</RouterLink></div><div v-if="project.isPending.value && projectId" class="empty-state"><h3>Loading your project…</h3></div>
  <template v-else-if="page === 'overview'">
    <div class="overview-actions"><span class="baseline-summary"><strong>Baseline</strong> {{ baselineLabel }}</span><div><RouterLink :to="`/projects/${projectId}/compare`" class="text-link">Compare runs <ArrowRight :size="15"/></RouterLink><RouterLink :to="`/projects/${projectId}/reviews`" class="text-link">Review cases</RouterLink></div></div>
    <div class="stat-grid"><article class="stat-card"><span>Experiments</span><strong>{{ project.data.value?.experiments.length || 0 }}</strong></article><article class="stat-card"><span>Dataset versions</span><strong>{{ versions('dataset').length }}</strong></article><article class="stat-card"><span>Latest {{ overviewMetric ? overviewMetric.replaceAll('_', ' ') : 'score' }}</span><strong>{{ percent(latest.data.value?.summary.metrics[overviewMetric]?.mean) }}</strong><small>{{ latest.data.value?.summary.metrics[overviewMetric]?.scored || 0 }} scored / {{ latest.data.value?.summary.total || 0 }} executions</small></article><article class="stat-card"><span>Latest coverage</span><strong>{{ percent(latest.data.value?.summary.metrics[overviewMetric]?.coverage) }}</strong><small>{{ latest.data.value?.summary.target_errors || 0 }} target errors</small></article></div>
    <div v-if="readiness.some(step => !step.done)" class="setup-checklist"><RouterLink v-for="(step, i) in readiness" :key="step.key" :to="`/projects/${projectId}/${step.key}`" :class="{ done: step.done }"><span class="step-number"><Check v-if="step.done" :size="16"/><template v-else>{{ i + 1 }}</template></span><span><strong>{{ step.label }}</strong><small>{{ step.hint }}</small></span><ArrowRight :size="15"/></RouterLink></div>
  </template>
  <section v-if="['overview','experiments'].includes(page)" class="panel"><div class="panel-header"><h2>{{ page === 'overview' ? 'Recent experiments' : 'Run history' }} <span class="count">{{ project.data.value?.experiments.length || 0 }}</span></h2><span class="muted">Auto-refreshing</span></div><div v-if="page === 'experiments'" class="table-toolbar"><input v-model="experimentSearch" aria-label="Search experiments" placeholder="Search experiments…"/><select v-model="experimentStatus" aria-label="Filter experiment status"><option value="">All statuses</option><option v-for="status in ['queued','running','completed','partially_failed','failed','canceled']" :key="status" :value="status">{{ human(status) }}</option></select><small>{{ visibleExperiments.length }} matching</small></div><table v-if="visibleExperiments.length"><thead><tr><th>Experiment</th><th>Status</th><th v-if="page !== 'overview'">Mode</th><th v-if="page !== 'overview'">Concurrency</th><th>Created</th></tr></thead><tbody><tr v-for="e in visibleExperiments.slice(0,page === 'overview' ? 6 : 100)" :key="e.id"><td><RouterLink :to="`/experiments/${e.id}`" class="strong-link">{{ e.name }}</RouterLink><small v-if="page !== 'overview'" class="block mono">{{ e.id.slice(0,8) }}</small></td><td><Status :value="e.status"/></td><td v-if="page !== 'overview'">{{ e.parent_id ? 'Rescore' : e.mode }}</td><td v-if="page !== 'overview'">{{ e.concurrency }}</td><td class="muted" :title="new Date(e.created_at).toLocaleString()">{{ page === 'overview' ? new Date(e.created_at).toLocaleDateString('en-US', { month: 'short', day: 'numeric' }) : new Date(e.created_at).toLocaleString() }}</td></tr></tbody></table><div v-else class="empty-state"><FlaskConical/><h3>{{ experimentSearch || experimentStatus ? 'No experiments match' : 'Your first experiment starts here' }}</h3><p>{{ experimentSearch || experimentStatus ? 'Try another search or clear the status filter.' : 'Select a dataset and evaluation suite, then call a target or import saved outputs.' }}</p><Button v-if="canEdit && !experimentSearch && !experimentStatus" @click="modal = 'launch'">Launch experiment</Button></div></section>
  <template v-if="['datasets','targets','evaluators'].includes(page)"><div class="table-toolbar standalone"><input v-model="resourceSearch" aria-label="Search resources" placeholder="Search by name…"/></div>
    <section v-for="kind in (page === 'evaluators' ? ['evaluator','suite'] : [page === 'datasets' ? 'dataset' : 'target'])" :key="kind" class="panel"><div class="panel-header"><h2>{{ kind === 'suite' ? 'Evaluation suites' : kind === 'evaluator' ? 'Evaluator library' : kind === 'dataset' ? 'Versioned datasets' : 'HTTP connections' }} <span class="count">{{ resources(kind).length }}</span></h2><Button v-if="canEdit && kind === 'suite'" variant="outline" size="sm" @click="openCreate('suite')">New suite</Button></div><table v-if="visibleResources(kind).length"><thead><tr><th>Name</th><th>Latest version</th><th>Configuration</th><th>Actions</th></tr></thead><tbody><tr v-for="r in visibleResources(kind)" :key="r.id"><td><button class="strong-link" @click="openEdit(r)">{{ r.name }}</button><small class="block mono">{{ r.id.slice(0,8) }}</small></td><td><span class="version-badge">v{{ r.versions[0]?.number }}</span> <small>{{ r.versions.length }} saved</small></td><td class="muted"><span v-if="kind === 'dataset'">{{ r.versions[0]?.config.held_out ? 'Held out' : 'Development' }}</span><span v-else-if="kind === 'target'" class="mono">{{ r.versions[0]?.config.endpoint }}</span><span v-else-if="kind === 'evaluator'">{{ human(r.versions[0]?.config.kind || '') }} · {{ r.versions[0]?.config.metric_key }}</span><span v-else>{{ r.versions[0]?.config.evaluator_version_ids.length }} evaluators</span></td><td><div class="inline-actions"><Button variant="outline" size="sm" @click="openEdit(r)">{{ canEdit ? 'Edit / versions' : 'Inspect versions' }}</Button><a v-if="kind === 'dataset'" :href="`/api/versions/${r.versions[0]?.id}/jsonl`" aria-label="Export JSONL"><Download :size="17"/></a><Button v-if="canEdit && kind === 'target'" variant="outline" size="sm" @click="selectedVersion = r.versions[0]!.id; modal = 'test'; testResult = null">Test</Button></div></td></tr></tbody></table><div v-else class="empty-state"><h3>{{ resourceSearch ? 'No matching resources' : `No ${kind} configured` }}</h3><Button v-if="canEdit && !resourceSearch" @click="openCreate(kind)">Create {{ kind }}</Button></div></section>
  </template>
  <template v-if="page === 'results' && experiment.data.value">
    <div class="experiment-toolbar"><Status :value="experiment.data.value.status"/><span class="mono muted">{{ experimentId.slice(0,8) }}</span><span>{{ experiment.data.value.mode }} · {{ experiment.data.value.concurrency }} concurrent · {{ experiment.data.value.repetitions }} replicate(s) · 0 warm-up</span><div class="spacer"></div><Button v-if="canEdit && ['queued','running'].includes(experiment.data.value.status)" variant="outline" @click="action(() => post(`/experiments/${experimentId}/cancel`), 'Cancellation requested')" :disabled="busy">Cancel</Button><Button v-if="canEdit && ['failed','partially_failed'].includes(experiment.data.value.status)" variant="outline" @click="action(() => post(`/experiments/${experimentId}/retry`), 'Failed work queued')">Retry failed work</Button><Button v-if="canEdit && experiment.data.value.status === 'completed'" variant="outline" @click="action(() => post(`/projects/${projectId}/baselines`, { experiment_id: experimentId }), 'Baseline pinned')" :disabled="busy"><Pin :size="14"/>Pin baseline</Button></div>
    <div class="run-progress" role="status"><div><strong>{{ progress.done }} / {{ progress.total }} executions settled</strong><span>{{ experiment.data.value.status === 'running' || experiment.data.value.status === 'queued' ? 'Updating every 2.5 seconds' : 'Saved result' }}</span></div><progress :value="progress.done" :max="progress.total || 1" aria-label="Experiment progress"/></div><div class="stat-grid"><article class="stat-card"><span>Executions</span><strong>{{ experiment.data.value.summary.total }}</strong><small>{{ experiment.data.value.summary.execution_states.completed || 0 }} completed</small></article><article class="stat-card"><span>Target errors</span><strong>{{ experiment.data.value.summary.target_errors }}</strong><small>Failures remain in denominators</small></article><article class="stat-card"><span>P95 target latency</span><strong class="smaller">{{ ms(experiment.data.value.summary.target_latency_ms.p95) }}</strong><small>Nearest rank · n={{ experiment.data.value.summary.target_latency_ms.n }}</small></article><article class="stat-card"><span>Target cost</span><strong class="smaller">{{ experiment.data.value.summary.target_cost.total_usd == null ? 'Unavailable' : `$${experiment.data.value.summary.target_cost.total_usd.toFixed(4)}` }}</strong><small>{{ experiment.data.value.summary.target_cost.provenance }}</small></article></div>
    <section class="panel"><div class="panel-header"><h2>Project criteria</h2><span class="muted">No universal aggregate score</span></div><table><thead><tr><th>Metric</th><th>Mean</th><th>Coverage</th><th>Pass / fail</th><th>N/A</th><th>Errors</th><th>Missing</th></tr></thead><tbody><tr v-for="(m,key) in experiment.data.value.summary.metrics" :key="key"><td class="mono">{{ key }}</td><td><strong>{{ percent(m.mean) }}</strong></td><td>{{ m.scored }}/{{ m.denominator }} ({{ percent(m.coverage) }})</td><td>{{ m.passed }} / {{ m.failed }}</td><td>{{ m.not_applicable }}</td><td>{{ m.errors }}</td><td>{{ m.missing }}</td></tr></tbody></table></section>
    <template v-for="(m,key) in experiment.data.value.summary.metrics" :key="String(key)"><section v-if="m.classification" class="panel pad"><h3>{{ key }} · classification metrics</h3><JsonView :value="m.classification"/></section></template>
    <section class="panel"><div class="panel-header"><h2>Case results</h2><select v-model="filter" aria-label="Filter case results"><option value="all">All cases</option><option value="failing">Failing scores</option><option value="errors">Execution errors</option></select></div><table><thead><tr><th>Case / replicate</th><th>Status</th><th>Criteria</th><th>Target latency</th><th>Review</th></tr></thead><tbody><tr v-for="row in filteredRows" :key="row.id"><td><RouterLink :to="`/cases/${row.id}`" class="strong-link mono">{{ row.case_id }} #{{ row.replicate }}</RouterLink><div class="tags"><span v-for="tag in row.case.tags" :key="tag">{{ tag }}</span></div></td><td><Status :value="row.status"/></td><td><span v-for="r in row.results" :key="r.metric_key" class="metric-pill" :class="r.status !== 'scored' ? 'muted' : r.passed ? 'pass' : 'fail'">{{ r.metric_key }} · {{ r.status !== 'scored' ? human(r.status) : r.passed ? 'pass' : 'fail' }} {{ r.score == null ? '—' : percent(r.score) }}</span></td><td class="mono">{{ ms(row.target_latency_ms) }}</td><td>{{ row.reviews.length ? `${row.reviews.length} assessment(s)` : 'Unreviewed' }}</td></tr></tbody></table></section>
    <div class="two-col"><section class="panel pad"><h3>Rescore saved outputs</h3><p>Create a linked evaluation without calling the target again.</p><label>Evaluation suite<select v-model="suiteId"><option v-for="v in versions('suite')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><Button variant="outline" :disabled="busy || ['queued','running'].includes(experiment.data.value.status)" v-if="canEdit" @click="rescore"><RotateCcw :size="14"/>Rescore outputs</Button></section><section class="panel pad"><h3>Human calibration</h3><p>{{ experiment.data.value.calibration.reviewed_decisions }} reviewed decisions · {{ percent(experiment.data.value.calibration.agreement) }} agreement</p><p>{{ experiment.data.value.calibration.disagreements.length }} disagreements. Automated judgments are preserved.</p><div class="inline-actions"><a class="text-link" :href="`/api/experiments/${experimentId}/report?format=json&metric=${Object.keys(experiment.data.value.summary.metrics)[0] || ''}`"><Download :size="15"/>JSON report</a><a class="text-link" :href="`/api/experiments/${experimentId}/report?format=junit&metric=${Object.keys(experiment.data.value.summary.metrics)[0] || ''}`">JUnit</a></div></section></div>
  </template>
  <template v-if="page === 'case' && execution.data.value">
    <div class="experiment-toolbar"><Status :value="execution.data.value.status"/><span>Replicate {{ execution.data.value.replicate }}</span><span>Target {{ ms(execution.data.value.target_latency_ms) }}</span><span>Evaluation {{ ms(execution.data.value.evaluation_latency_ms) }}</span><span v-if="execution.data.value.late_completion" class="warning-chip">Finished after cancellation</span></div><div v-if="execution.data.value.target_error" class="error">{{ execution.data.value.target_error }}</div>
    <div class="two-col"><section class="panel"><div class="panel-header"><h2>Target input</h2></div><JsonView :value="execution.data.value.case.input"/></section><section class="panel"><div class="panel-header"><h2>Actual output</h2></div><JsonView :value="execution.data.value.output" :missing="!execution.data.value.output_present"/></section><section class="panel"><div class="panel-header"><h2>Reference output</h2><small>Evaluator only</small></div><JsonView :value="execution.data.value.case.expected" :missing="!('expected' in execution.data.value.case)"/></section><section class="panel"><div class="panel-header"><h2>Context & criteria</h2><small>Evaluator only</small></div><JsonView :value="{ context: execution.data.value.case.context, acceptance_criteria: execution.data.value.case.acceptance_criteria }"/></section></div>
    <section class="panel"><div class="panel-header"><h2>Evaluator evidence</h2></div><div v-for="r in execution.data.value.results" :key="r.metric_key" class="evaluator-row"><div><strong class="mono">{{ r.metric_key }}</strong><p>{{ r.explanation }}</p><small class="mono">{{ r.evidence.join(', ') }} · version {{ r.evaluator_version.slice(0,8) }}</small></div><Status :value="r.status !== 'scored' ? r.status : r.passed ? 'pass' : 'fail'"/></div></section>
    <div class="two-col"><section class="panel pad"><h3>Observable tool-call trace</h3><JsonView :value="execution.data.value.trace"/><h3>Telemetry & provenance</h3><JsonView :value="execution.data.value.metadata"/></section><section class="panel pad"><h3>Independent human assessment</h3><p>Saving a review preserves the automated judgment.</p><form v-if="canEdit" @submit.prevent="saveReview"><label>Metric<select v-model="reviewMetric"><option v-for="r in execution.data.value.results" :key="r.metric_key">{{ r.metric_key }}</option></select></label><label>Human decision<select v-model="reviewPassed"><option :value="true">Pass</option><option :value="false">Fail</option></select></label><label>Assessment note<textarea v-model="reviewNote" required placeholder="Explain the decision using observable evidence."/></label><Button type="submit" :disabled="busy || !reviewMetric">Save human assessment</Button></form><div v-for="r in execution.data.value.reviews" :key="r.id" class="review-note"><Status :value="r.passed ? 'pass' : 'fail'"/><p>{{ r.note }}</p><small>{{ new Date(r.created_at).toLocaleString() }}</small></div></section></div><section class="panel"><div class="panel-header"><h2>Attempt history</h2><small>First successful target attempt contributes.</small></div><table><thead><tr><th>Phase</th><th>Attempt</th><th>Outcome</th><th>Error</th></tr></thead><tbody><tr v-for="a in execution.data.value.attempts" :key="a.id"><td>{{ a.phase }}</td><td>{{ a.number }}</td><td><Status :value="a.status"/></td><td>{{ a.error || '—' }}</td></tr></tbody></table></section>
  </template>
  <section v-if="page === 'reviews'" class="panel"><div class="table-toolbar"><input v-model="reviewSearch" aria-label="Search review cases" placeholder="Search cases or experiments…"/><small>Cases from the 10 most recent completed runs.</small></div><div class="panel-header"><h2>Calibration queue <span class="count">{{ displayReviews.length }}</span></h2><label class="check-label"><input v-model="onlyUnreviewed" type="checkbox"/>Unreviewed only</label></div><table v-if="displayReviews.length"><thead><tr><th>Case</th><th>Experiment</th><th>Automated criteria</th><th>Human assessments</th><th></th></tr></thead><tbody><tr v-for="row in displayReviews" :key="row.id"><td class="mono">{{ row.case_id }} #{{ row.replicate }}</td><td>{{ row.experiment_name }}</td><td><span v-for="r in row.results" :key="r.metric_key" class="metric-pill" :class="r.status !== 'scored' ? 'muted' : r.passed ? 'pass' : 'fail'">{{ r.metric_key }} · {{ r.status !== 'scored' ? human(r.status) : r.passed ? 'pass' : 'fail' }}</span></td><td>{{ row.reviews.length }}</td><td><RouterLink :to="`/cases/${row.id}`" class="text-link">Review <ArrowRight :size="15"/></RouterLink></td></tr></tbody></table><div v-else class="empty-state"><Check/><h3>No cases waiting for review</h3><p>Completed experiments populate this queue.</p></div></section>
  <div v-if="page === 'gates'" class="two-col"><GateEditor v-if="gateConfig.data.value" :project-id="projectId" :config="gateConfig.data.value" :metrics="metricKeys" :readonly="!canEdit" @saved="gateConfig.refetch()"/><section class="panel pad"><h3>Evaluate a release</h3><label>Experiment<select v-model="gateExperiment"><option v-for="e in project.data.value?.experiments" :key="e.id" :value="e.id">{{ e.name }}</option></select></label><label>Comparison metric<select v-model="metric"><option v-for="m in metricKeys" :key="m">{{ m }}</option></select></label><Button :disabled="!gateExperiment || busy" @click="action(async () => { gateResult = await api(`/experiments/${gateExperiment}/gate?metric=${encodeURIComponent(metric)}`) }, 'Gate evaluated')"><ShieldCheck :size="16"/>Evaluate gate</Button><div v-if="gateResult" class="gate-result" :class="gateResult.passed ? 'pass' : 'fail'"><h3>{{ gateResult.passed ? 'Gate passed' : gateResult.exit_code === 2 ? 'Infrastructure / configuration error' : 'Quality gate failed' }}</h3><p>Exit code {{ gateResult.exit_code }}</p><ul><li v-for="reason in [...gateResult.quality_failures,...gateResult.infrastructure_errors]" :key="reason">{{ reason }}</li></ul><small class="mono">Pinned baseline: {{ gateResult.pinned_baseline_id || 'none' }}</small></div><div v-if="gateExperiment" class="inline-actions report-actions"><a class="text-link" :href="`/api/experiments/${gateExperiment}/report?format=json&metric=${metric}`"><Download :size="15"/>JSON</a><a class="text-link" :href="`/api/experiments/${gateExperiment}/report?format=junit&metric=${metric}`">JUnit</a><Button variant="outline" size="sm" @click="action(() => post(`/experiments/${gateExperiment}/artifacts?metric=${metric}`), 'Report snapshot persisted')">Save snapshot</Button></div><h3>CI command</h3><pre class="json-view">evaldock gate {{ gateExperiment || '&lt;experiment-id&gt;' }} --metric {{ metric }}</pre></section></div>
  <template v-if="page === 'settings'"><div class="two-col"><section class="panel pad"><h3>Credentials</h3><p>Saved values are encrypted and hidden.</p><div v-for="c in settingsData.data.value?.credentials" :key="c.id" class="credential-row"><strong>{{ c.name }}</strong><span>{{ c.value }}</span></div><form v-if="canEdit" @submit.prevent="createSecret"><label>Name<input v-model="secretName" required/></label><label>Secret<input v-model="secretValue" type="password" autocomplete="new-password" required/></label><Button type="submit" :disabled="busy">Save credential</Button></form></section><section class="panel pad"><h3>Workspace API tokens</h3><form @submit.prevent="createToken"><label>Token name<input v-model="tokenName" required/></label><div class="form-grid"><label>Token access<select v-model="tokenScope"><option value="read">Read only</option><option v-if="canEdit" value="write">Read & write</option></select></label><label>Expires in (days)<input v-model.number="tokenDays" type="number" min="1" max="365" required/></label></div><Button type="submit" :disabled="busy">Create token</Button></form><div v-if="newToken" class="token-reveal"><strong>Copy this token before leaving.</strong><pre class="json-view">{{ newToken }}</pre><Button type="button" variant="outline" size="sm" @click="copyToken">{{ copied ? 'Copied' : 'Copy token' }}</Button><Button type="button" variant="ghost" size="sm" @click="newToken = ''">Hide token</Button></div><div v-for="t in workspaceTokens.filter(t => !t.revoked)" :key="t.id" class="credential-row"><span>{{ t.name }} · {{ t.scopes.join(', ') }}</span><Button size="sm" variant="outline" @click="action(() => api(`/tokens/${t.id}`, { method: 'DELETE' }), 'Token revoked')">Revoke</Button></div><details v-if="workspaceTokens.some(t => t.revoked)" class="revoked-tokens"><summary>Revoked tokens</summary><div v-for="t in workspaceTokens.filter(t => t.revoked)" :key="t.id" class="credential-row"><span>{{ t.name }}</span><small>{{ t.scopes.join(', ') }}</small></div></details></section></div><details class="panel pad settings-details"><summary>Workspace members</summary><table><thead><tr><th>Member</th><th>Email</th><th>Role</th></tr></thead><tbody><tr v-for="m in settingsData.data.value?.members" :key="m.id"><td>{{ m.name }}</td><td>{{ m.email }}</td><td>{{ m.role }}</td></tr></tbody></table><form v-if="canAdmin" class="member-form" @submit.prevent="action(async () => { await post(`/workspaces/${project.data.value?.workspace_id}/members`, member); member.password = '' }, 'Workspace member added')"><label>Name<input v-model="member.name" required/></label><label>Email<input v-model="member.email" type="email" required/></label><label>Initial password<input v-model="member.password" type="password" minlength="12" required/></label><label>Role<select v-model="member.role"><option>viewer</option><option>editor</option><option>owner</option></select></label><Button type="submit">Add member</Button></form></details><details class="panel settings-details"><summary>Activity</summary><table><thead><tr><th>Action</th><th>Time</th><th>Record</th></tr></thead><tbody><tr v-for="a in settingsData.data.value?.audit" :key="a.id"><td>{{ a.action }}</td><td>{{ new Date(a.created_at).toLocaleString() }}</td><td class="mono">{{ JSON.stringify(a.detail) }}</td></tr></tbody></table></details><details v-if="project.data.value?.description" class="panel pad settings-details"><summary>Project notes</summary><p>{{ project.data.value.description }}</p></details><Button v-if="canEdit" variant="outline" @click="modal = 'project'; formName = ''">Create another project</Button></template>
  <ResourceEditor v-if="modal === 'resource' && project.data.value" :project="project.data.value" :kind="editorKind" :resource="selectedResource" :readonly="!canEdit" @close="modal = ''" @saved="resourceSaved"/><ModalFrame v-if="modal && modal !== 'resource'" :title="modal === 'launch' ? 'Launch experiment' : modal === 'test' ? 'Test target connection' : 'New project'" :busy="busy" @close="closeModal"><div class="modal-body"><div v-if="error" class="error" role="alert">{{ error }}</div>
    <form v-if="modal === 'launch'" @submit.prevent="launchExperiment"><div v-if="launchMissing" class="warning-strip">{{ launchMissing }}</div><div class="launch-summary"><span class="eyebrow">RUN SUMMARY</span><strong>{{ plannedCalls }} planned executions</strong><small>{{ launchDataset.data.value?.cases.length || 0 }} cases × {{ repetitions }} repetition(s) · {{ concurrency }} concurrent</small><small>Main baseline: {{ baselineLabel }}</small></div><label>Experiment name<input v-model="launchName" placeholder="e.g. Prompt v3 · candidate"/></label><label>Dataset version<select v-model="datasetId" required><option v-for="v in versions('dataset')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><label>Execution mode<select v-model="launchMode"><option value="http">HTTP target</option><option value="imported">Imported outputs</option></select></label><label v-if="launchMode === 'http'">Target version<select v-model="targetId" required><option v-for="v in versions('target')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><ImportedOutputEditor v-else v-model="imported" :cases="launchDataset.data.value?.cases || []" :repetitions="Number(repetitions)" @validity="launchValid = $event"/><label>Evaluation suite<select v-model="suiteId" required><option v-for="v in versions('suite')" :key="v.id" :value="v.id">{{ v.label }}</option></select></label><div class="two-col"><label>Repetitions<input v-model="repetitions" type="number" min="1" max="20" required/></label><label>Concurrency<input v-model="concurrency" type="number" min="1" max="16" required/></label></div><label v-if="launchMode === 'http'">Optional target call budget<input v-model="budget" type="number" min="1" placeholder="Unlimited"/></label><p class="muted">The main baseline is pinned when you launch. Only case input is sent to targets. Use test endpoints: target calls may have side effects.</p><Button type="submit" :disabled="busy || !!launchMissing || !launchValid"><Play :size="15"/>{{ busy ? 'Launching…' : 'Launch experiment' }}</Button></form>
    <form v-else-if="modal === 'test'" @submit.prevent="action(async () => { testResult = await post(`/targets/${selectedVersion}/test`, { input: testJson }) }, 'Connection test completed')"><p>This sends one real request to the configured test endpoint.</p><JsonField v-model="testJson" label="Target input JSON" :rows="10" @validity="testValid = $event"/><Button type="submit" :disabled="busy || !testValid">Send test request</Button><JsonView v-if="testResult" :value="testResult"/></form>
    <form v-else @submit.prevent="action(async () => { const p = await post<Project>('/projects', { name: formName, workspace_id: project.data.value?.workspace_id }); modal = ''; router.push(`/projects/${p.id}/overview`) }, 'Project created')"><label>Project name<input v-model="formName" required/></label><Button type="submit">Create project</Button></form>
  </div></ModalFrame>
</main>
</template>
